'use strict';
(() => {
 const model=window.CP_MODEL;if(!model)return;
 const {topics,parties,questions,quickIds}=model;
 const labels=['Totalmente en desacuerdo','En desacuerdo','Ni de acuerdo ni en desacuerdo','De acuerdo','Totalmente de acuerdo'];
 const el=id=>document.getElementById(id),escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 if(!el('quiz'))return;
 let mode=null,activeQuestions=[],answers=[],weights=[],visited=[],index=0,currentView='home',lastRanking=[];
 function show(view){if(view!=='home')el('connection-video')?.pause();window.speechSynthesis?.cancel();currentView=view;['home','quiz','results'].forEach(v=>el(v).hidden=v!==view);window.scrollTo({top:0,behavior:'instant'});}
 function startTest(testMode){if(!['quick','full'].includes(testMode))throw Error('Modalidad inválida');mode=testMode;activeQuestions=testMode==='quick'?quickIds.map(i=>questions[i]):questions;answers=Array(activeQuestions.length).fill(null);weights=Array(activeQuestions.length).fill(mode==='full'?3:1);visited=Array(activeQuestions.length).fill(false);index=0;lastRanking=[];show('quiz');renderQuestion();el('question-heading').focus({preventScroll:true});}
 function renderQuestion(){
  window.speechSynthesis?.cancel();const q=activeQuestions[index],completed=visited.filter(Boolean).length;
  el('quiz').innerHTML=`<div class="quiz-top"><button class="text-button" id="exit-quiz">‹ Volver al inicio</button><span>Test ${mode==='quick'?'rápido':'completo'} · ${activeQuestions.length} preguntas</span></div><div class="quiz-progress" role="progressbar" aria-label="Preguntas revisadas" aria-valuemin="0" aria-valuemax="${activeQuestions.length}" aria-valuenow="${completed}"><div style="width:${completed/activeQuestions.length*100}%"></div></div><div class="quiz-content"><span class="question-topic">${topics[q.topic].name}</span><h1 id="question-heading" tabindex="-1">${q.text}</h1><details class="question-context"><summary>Entender la afirmación</summary><p>${q.explanation}</p></details><p class="quiz-instruction">¿Hasta qué punto estás de acuerdo?</p><div class="rating-options" role="radiogroup" aria-labelledby="question-heading">${labels.map((label,i)=>`<button type="button" class="rating-button" role="radio" aria-checked="${answers[index]===i+1}" data-answer="${i+1}" aria-label="${i+1}: ${label}" tabindex="${answers[index]===i+1||answers[index]===null&&i===0?0:-1}"><strong>${i+1}</strong><span>${label}</span></button>`).join('')}</div><p class="rating-detail" aria-live="polite">${answers[index]===null?'1: totalmente en desacuerdo · 5: totalmente de acuerdo':labels[answers[index]-1]}</p>${mode==='full'?`<div class="importance"><label for="importance-value">¿Cuánto te importa? <strong id="importance-label">${weights[index]}/5</strong></label><input id="importance-value" type="range" min="1" max="5" step="1" value="${weights[index]}"><div><span>Poco</span><span>Mucho</span></div></div>`:''}<div class="quiz-tools"><button class="text-button" id="skip-question">No lo sé / omitir</button>${'speechSynthesis' in window?'<button class="text-button" id="read-question">Escuchar pregunta</button>':''}</div><div class="quiz-controls"><button class="button light-button" id="previous-question" ${index===0?'disabled':''}>Anterior</button><span class="answered-counter">Pregunta ${index+1} de ${activeQuestions.length}</span><button class="button dark-button" id="next-question" ${answers[index]===null&&!visited[index]?'disabled':''}>${index===activeQuestions.length-1?'Ver resultados':'Continuar'}</button></div><p id="quiz-status" role="status" class="form-status"></p><details class="review-jump"><summary>Ver progreso y revisar preguntas</summary><div class="question-map">${activeQuestions.map((item,i)=>`<button class="question-jump ${visited[i]?'done':''}" data-jump="${i}" aria-label="Pregunta ${i+1}: ${visited[i]?answers[i]===null?'omitida':'respondida':'pendiente'}" ${i===index?'aria-current="step"':''}>${i+1}</button>`).join('')}</div></details></div>`;
  el('exit-quiz').onclick=()=>el('exit-dialog').showModal();el('previous-question').onclick=()=>navigate(-1);el('next-question').onclick=nextQuestion;
  el('skip-question').onclick=()=>{answers[index]=null;visited[index]=true;nextQuestion();};
  el('importance-value')?.addEventListener('input',e=>{weights[index]=Number(e.target.value);el('importance-label').textContent=weights[index]+'/5';});
  el('read-question')?.addEventListener('click',()=>{window.speechSynthesis.cancel();const voice=new SpeechSynthesisUtterance(q.text);voice.lang='es-ES';window.speechSynthesis.speak(voice);});
  el('quiz').querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{index=Number(b.dataset.jump);renderQuestion();el('question-heading').focus({preventScroll:true});});
  el('quiz').querySelectorAll('[data-answer]').forEach(b=>{b.onclick=()=>selectAnswer(Number(b.dataset.answer));b.onkeydown=e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(e.key)){e.preventDefault();let v=Number(b.dataset.answer);v=e.key==='Home'?1:e.key==='End'?5:Math.max(1,Math.min(5,v+(['ArrowRight','ArrowDown'].includes(e.key)?1:-1)));selectAnswer(v);el('quiz').querySelector(`[data-answer="${v}"]`).focus();}}});
 }
 function selectAnswer(value){if(!Number.isInteger(value)||value<1||value>5)throw Error('Respuesta inválida');answers[index]=value;visited[index]=true;el('quiz').querySelectorAll('[data-answer]').forEach(b=>{b.setAttribute('aria-checked',String(Number(b.dataset.answer)===value));b.tabIndex=Number(b.dataset.answer)===value?0:-1;});el('next-question').disabled=false;el('quiz').querySelector('.rating-detail').textContent=labels[value-1];const n=visited.filter(Boolean).length;const progress=el('quiz').querySelector('.quiz-progress');progress.setAttribute('aria-valuenow',n);progress.firstElementChild.style.width=`${n/activeQuestions.length*100}%`;}
 function navigate(delta){const next=index+delta;if(next<0||next>=activeQuestions.length)return;index=next;renderQuestion();el('question-heading').focus({preventScroll:true});}
 function nextQuestion(){if(!visited[index])return;if(index===activeQuestions.length-1){if(answers.filter(a=>a!==null).length<10){el('quiz-status').textContent='Necesitas al menos 10 respuestas para obtener un resultado. Puedes volver a las preguntas anteriores con el mapa de progreso.';return;}renderResults();}else navigate(1);}
 function score(partyIndex,subset=activeQuestions){const ids=new Set(subset.map(q=>q.id));let distance=0,totalWeight=0,count=0;activeQuestions.forEach((q,i)=>{const position=q.positions[partyIndex];if(ids.has(q.id)&&answers[i]!==null&&position!==null){distance+=weights[i]*Math.abs(answers[i]-position);totalWeight+=weights[i];count++;}});return {score:totalWeight?100*(1-distance/(4*totalWeight)):null,count};}
 function computeRanking(){const answered=answers.filter(a=>a!==null).length;return parties.map((p,i)=>{const s=score(i);return {...p,partyIndex:i,score:s.count>=5?s.score:null,count:s.count,coverage:Math.round(s.count/answered*100)};}).sort((a,b)=>(b.score??-1)-(a.score??-1)||a.name.localeCompare(b.name,'es'));}
 function axisValue(axis){let n=0,total=0,count=0;activeQuestions.forEach((q,i)=>{if(q.axis===axis&&answers[i]!==null){n+=(answers[i]-3)/2*q.polarity*weights[i];total+=weights[i];count++;}});return count>=3?n/total:null;}
 function compassMarkup(){const eco=axisValue('economic'),social=axisValue('social');return `<div class="compass" aria-label="Brújula política: eje horizontal económico y vertical social"><span class="compass-top">Más libertad social</span><span class="compass-left">Más intervención pública</span><span class="compass-right">Más mercado</span><span class="compass-bottom">Más restricción social</span>${eco!==null&&social!==null?`<span class="compass-dot" style="left:${50-eco*39}%;top:${50-social*39}%" aria-label="Tu posición"><span>Tú</span></span>`:'<span class="compass-placeholder">Responde al menos 3 preguntas de cada eje para mostrar tu punto.</span>'}</div><p class="note">Una síntesis de tus respuestas económicas y sociales. No es una etiqueta fija ni incluye todas tus opiniones.</p>`;}
 function renderResults(){
  lastRanking=computeRanking();show('results');const winner=lastRanking.find(p=>p.score!==null),answered=answers.filter(a=>a!==null).length;
  const tied=winner?lastRanking.filter(p=>p.score!==null&&Math.abs(p.score-winner.score)<1e-9):[];
  let rank=0,previous=null;
  el('results').innerHTML=`<div class="result-intro"><span class="eyebrow">TUS IDEAS, EN PERSPECTIVA</span><h1 tabindex="-1">Esta es tu conexión.</h1><p>Test ${mode==='quick'?'rápido':'completo'} · ${answered} respuestas · ${activeQuestions.length-answered} omitidas</p>${winner?`<div class="winner-card"><div><div class="winner-logos">${tied.map(p=>`<img class="party-logo" src="${p.logo}" alt="Logo de ${p.name}" width="64" height="52">`).join('')}</div><span class="eyebrow">MAYOR AFINIDAD EN LAS COMPARACIONES DISPONIBLES</span><div class="winner-name">${tied.map(p=>p.name).join(' · ')}</div><div class="winner-subtitle">${tied.length>1?'Empate en porcentaje · Revisa la cobertura de cada perfil':winner.count+' afirmaciones comparadas · Cobertura '+winner.coverage+'%'+(winner.coverage<80?' · Perfil parcial':'')}</div></div><div class="winner-score">${Math.round(winner.score)}<span>%</span></div></div>`:''}<p class="result-note">Perfiles editoriales orientativos. Compara la cobertura antes de interpretar el orden: una afinidad parcial utiliza menos cuestiones. No es una recomendación de voto.</p></div><div class="result-columns"><section class="ranking-panel"><h2>Tu afinidad, partido a partido.</h2><p class="panel-intro">Los 15 perfiles, ordenados por su porcentaje sin redondear. Los empates exactos comparten posición.</p>${lastRanking.map((p,i)=>{if(p.score!==previous)rank=i+1;previous=p.score;return `<div class="party-row" style="--party-color:${p.color};animation-delay:${i*.025}s"><span class="party-rank">${p.score===null?'—':String(rank).padStart(2,'0')}</span><img class="party-logo" src="${p.logo}" alt="Logo de ${p.name}" width="56" height="44" decoding="async"><div class="party-text"><a href="/partidos/${p.slug}/"><strong>${p.name}</strong></a><small>${p.count} comparadas · ${p.coverage}% cobertura</small><div class="party-bar"><span style="width:${p.score??0}%"></span></div></div><span class="party-percent">${p.score===null?'—':Math.round(p.score)+'%'}</span></div>`;}).join('')}<p class="note">—: menos de 5 comparaciones. Democracia21 tiene un perfil documentado parcialmente; los demás son estimaciones editoriales por tema.</p></section><aside class="themes-panel"><h2>Tu brújula política.</h2>${compassMarkup()}<a class="text-link" href="/metodologia/">Entender los ejes y la fórmula →</a></aside></div><section class="result-detail"><h2>Compara dos conexiones.</h2><p>Elige partidos y observa la afinidad en cada tema. Un porcentaje por tema puede basarse en pocas preguntas.</p><div class="compare-selects"><label>Primer partido<select id="compare-one">${lastRanking.map(p=>`<option value="${p.partyIndex}">${p.name}</option>`).join('')}</select></label><label>Segundo partido<select id="compare-two">${lastRanking.map((p,i)=>`<option value="${p.partyIndex}" ${i===1?'selected':''}>${p.name}</option>`).join('')}</select></label></div><div id="topic-comparison"></div></section><details class="answer-review"><summary>Revisar mis ${answered} respuestas</summary><div>${activeQuestions.map((q,i)=>`<div class="review-row"><div><strong>${i+1}. ${q.text}</strong><small>${answers[i]===null?'Omitida':labels[answers[i]-1]}${mode==='full'?' · Importancia '+weights[i]+'/5':''}</small></div><button class="text-button" data-review="${i}">Cambiar</button></div>`).join('')}</div></details><div class="result-actions"><button class="button light-button" id="download-results">Descargar informe CSV</button><button class="button light-button" id="print-results">Guardar como PDF / imprimir</button><button class="button dark-button" id="share-results">Compartir resumen</button><button class="button light-button" id="another-test">Elegir otro test</button></div><p role="status" id="result-status" class="form-status"></p><p class="result-note">La descarga incluye tus respuestas y prioridades. Compartir solo prepara un resumen de afinidades. Tus respuestas no se envían al servidor.</p>`;
  el('results').querySelector('h1').focus({preventScroll:true});
  el('compare-one').onchange=renderComparison;el('compare-two').onchange=renderComparison;renderComparison();
  el('results').querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>{index=Number(b.dataset.review);show('quiz');renderQuestion();el('question-heading').focus({preventScroll:true});});
  el('another-test').onclick=resetHome;el('download-results').onclick=download;el('print-results').onclick=()=>window.print();el('share-results').onclick=share;
 }
 function renderComparison(){const a=Number(el('compare-one').value),b=Number(el('compare-two').value);el('topic-comparison').innerHTML=topics.map((t,i)=>{const subset=activeQuestions.filter(q=>q.topic===i);return `<div class="comparison-row"><a href="/temas/${t.slug}/">${t.name}</a>${[a,b].map(pi=>{const v=score(pi,subset);return `<div style="--party-color:${parties[pi].color}"><span>${parties[pi].name}: ${v.count?Math.round(v.score)+'%':'Sin datos'} <small>(${v.count})</small></span><div class="party-bar"><span style="width:${v.score??0}%"></span></div></div>`;}).join('')}</div>`;}).join('');}
 function csvCell(v){return '"'+String(v??'').replace(/"/g,'""')+'"';}
 function download(){const rows=[['Conexión Política','Informe personal',model.version],['Modalidad',mode==='quick'?'Rápido':'Completo'],[],['Partido','Afinidad (%)','Preguntas comparadas','Cobertura (%)'],...lastRanking.map(p=>[p.name,p.score===null?'Sin datos suficientes':p.score.toFixed(2),p.count,p.coverage]),[],['Pregunta','Tema','Afirmación','Respuesta','Importancia'],...activeQuestions.map((q,i)=>[i+1,topics[q.topic].name,q.text,answers[i]??'Omitida',weights[i]])];const blob=new Blob(['\ufeff'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='conexion-politica-mi-informe.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);el('result-status').textContent='Informe preparado. Contiene tus opiniones: elige dónde conservarlo.';}
 async function share(){const text='Mi afinidad orientativa en Conexión Política:\n'+lastRanking.filter(p=>p.score!==null).slice(0,3).map(p=>`${p.name}: ${Math.round(p.score)}% (${p.coverage}% de cobertura)`).join('\n')+'\nPerfiles editoriales; no es una recomendación de voto.\nhttps://conexion-politica.onrender.com/';try{if(navigator.share)await navigator.share({title:'Mi conexión política',text});else{await navigator.clipboard.writeText(text);el('result-status').textContent='Resumen copiado. Puedes revisarlo antes de compartirlo.';}}catch(e){if(e.name!=='AbortError')el('result-status').textContent='No se pudo compartir automáticamente. Puedes descargar tu informe.';}}
 function resetHome(){mode=null;activeQuestions=[];answers=[];weights=[];visited=[];index=0;lastRanking=[];show('home');el('exit-dialog').close();}
 document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>startTest(b.dataset.start));document.querySelectorAll('[data-method]').forEach(b=>b.onclick=()=>{window.location.href='/metodologia/';});
 el('stay-quiz').onclick=()=>el('exit-dialog').close();el('confirm-exit').onclick=resetHome;
 document.querySelector('.site-header .brand').onclick=e=>{if(currentView==='quiz'){e.preventDefault();el('exit-dialog').showModal();}else if(currentView==='results'){e.preventDefault();resetHome();}};
 for(const d of document.querySelectorAll('dialog'))d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});
 const how=document.querySelector('.how-strip');if(how&&'IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target);}}),{threshold:.15});how.classList.add('reveal');observer.observe(how);}
 // Decorative motion: select a single asset, never expose player controls.
 const video=el('connection-video');if(video){const mobile=window.matchMedia('(max-width:767px)'),reduced=window.matchMedia('(prefers-reduced-motion:reduce)');let visible=false,selected='';
  const play=()=>{if(!visible||el('home').hidden||document.hidden||reduced.matches)return;if(video.getAttribute('src')!==selected){video.src=selected;video.load();}if(video.paused)video.play().catch(()=>{});};
  const select=()=>{const layout=mobile.matches?'mobile':'desktop',src=video.dataset[layout+'Src'];if(selected===src)return;video.pause();selected=src;video.dataset.layout=layout;video.poster=video.dataset[layout+'Poster'];video.defaultMuted=true;video.muted=true;video.volume=0;video.controls=false;if(video.hasAttribute('src')){video.removeAttribute('src');video.load();}play();};select();mobile.addEventListener('change',select);
  if('IntersectionObserver' in window){new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(visible)play();else video.pause();},{threshold:.15}).observe(video);}else{visible=true;play();}
  reduced.addEventListener('change',()=>{if(reduced.matches)video.pause();else play();});document.addEventListener('visibilitychange',()=>{if(document.hidden)video.pause();else play();});window.addEventListener('pagehide',()=>video.pause());
 }
})();
